package cn.edu.lostfound.controller;
import cn.edu.lostfound.dto.*; import cn.edu.lostfound.entity.Item; import cn.edu.lostfound.security.UserContext; import cn.edu.lostfound.service.ItemService;
import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/items") public class ItemController {private final ItemService service;public ItemController(ItemService s){service=s;}@PostMapping public ApiResponse<Item> create(@Valid @RequestBody ItemDtos.Save r){return ApiResponse.ok(service.create(UserContext.id(),r));}@GetMapping public ApiResponse<List<Item>> search(@RequestParam(defaultValue="")String keyword,@RequestParam(defaultValue="")String type){return ApiResponse.ok(service.search(keyword,type));}@GetMapping("/mine")public ApiResponse<List<Item>> mine(){return ApiResponse.ok(service.mine(UserContext.id()));}@PutMapping("/{id}")public ApiResponse<Item> update(@PathVariable Long id,@Valid @RequestBody ItemDtos.Save r){return ApiResponse.ok(service.update(id,UserContext.id(),UserContext.admin(),r));}@GetMapping("/{id}/matches")public ApiResponse<List<Map<String,Object>>> matches(@PathVariable Long id){return ApiResponse.ok(service.matches(id,UserContext.id(),UserContext.admin()));}}
